(function(){'use strict';
const C=GearCore,$=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
const presets=[
{title:'01 · 大小与转速',desc:'20 齿带动 40 齿，观察减速与反向。',gears:[{id:'A',z:20,x:400,y:285},{id:'B',z:40,x:520,y:285}],output:'B',label:'实验 01 / 齿数与转速',heading:'小齿轮带大齿轮，为什么转得慢？'},
{title:'02 · 惰轮的作用',desc:'加入中间轮，输出旋向再次改变。',gears:[{id:'A',z:20,x:250,y:290},{id:'B',z:40,x:370,y:290},{id:'C',z:60,x:570,y:290}],output:'C',label:'实验 02 / 传动路径',heading:'多一个中间轮，会改变总传动比吗？'},
{title:'03 · 无法转动的闭环',desc:'三个齿轮两两啮合，发现约束冲突。',gears:[{id:'A',z:40,x:420,y:245},{id:'B',z:40,x:580,y:245},{id:'C',z:40,x:500,y:245+Math.sqrt(3)*80}],output:'C',label:'实验 03 / 约束冲突',heading:'三个齿轮首尾相接，为什么卡住？'}];
const challenges=[
{title:'01 · 做一个减速器',desc:'只用两个齿轮，让 B 与 A 反向，输出转速为输入的 1/2。',hint:'输出轮的齿数应为主动轮的两倍，例如 A 20 齿、B 40 齿。',gears:[{id:'A',z:20,x:400,y:290},{id:'B',z:20,x:480,y:290}],output:'B',check:s=>s.gears.length===2&&s.motor==='A'&&s.output==='B'&&near(s.result.ratios.B,-.5),solution:0},
{title:'02 · 同向减速',desc:'用三个齿轮，让 C 与 A 同向，输出转速为输入的 1/3。',hint:'A 20 齿、C 60 齿，中间增加一个惰轮。它改变旋向，不改变首末齿数比。',gears:[{id:'A',z:20,x:250,y:290},{id:'B',z:40,x:370,y:290},{id:'C',z:40,x:530,y:290}],output:'C',check:s=>s.gears.length===3&&s.motor==='A'&&s.output==='C'&&near(s.result.ratios.C,1/3),solution:1},
{title:'03 · 修复传动闭环',desc:'保留三个 40 齿齿轮，移动位置，让 A、B、C 连成可转动的传动链，A 驱动 C 输出。',hint:'移开一处啮合。把三个齿轮排成直线，是一个可行的办法。',gears:presets[2].gears,output:'C',check:s=>s.gears.length===3&&s.gears.every(g=>g.z===40)&&s.motor==='A'&&s.output==='C'&&s.result.edges.length===2&&Object.keys(s.result.ratios).length===3,solution:2}];
function near(a,b){return Number.isFinite(a)&&Math.abs(a-b)<1e-7;}
let done=[];try{done=JSON.parse(localStorage.getItem('gear-workshop-progress')||'[]').filter(x=>[0,1,2].includes(x));}catch{}
let state={gears:[],motor:'A',output:'C',selected:'C',speed:20,direction:1,running:!matchMedia('(prefers-reduced-motion: reduce)').matches,mode:'free',lesson:1,task:0,phase:0,result:null};
let drag=null,last=0,toastTimer;const rotating=new Map;
function node(tag,attrs={},text){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function reset(){const p=state.mode==='challenge'?challenges[state.task]:presets[state.lesson];state.gears=p.gears.map(g=>({...g}));state.motor='A';state.output=p.output;state.selected=p.output;state.phase=0;draw();}
function modeUI(){document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));$('progress').textContent=done.length+'/3';$('leftTitle').textContent=state.mode==='free'?'零件架':state.mode==='learn'?'实验目录':'挑战目录';const box=$('modeContent');box.replaceChildren();if(state.mode!=='free'){const opts=document.createElement('div');opts.className='mode-options';const list=state.mode==='learn'?presets:challenges;list.forEach((p,i)=>{const b=document.createElement('button');b.textContent=p.title+(state.mode==='challenge'&&done.includes(i)?' ✓':'');b.classList.toggle('chosen',i===(state.mode==='learn'?state.lesson:state.task));b.onclick=()=>{if(state.mode==='learn')state.lesson=i;else state.task=i;modeUI();reset();};opts.append(b);});box.append(opts);if(state.mode==='challenge'){const task=challenges[state.task],card=document.createElement('div');card.className='task-box';card.innerHTML='<strong>本关目标</strong>';const description=document.createElement('div');description.textContent=task.desc;card.append(description);const hint=document.createElement('button');hint.textContent='查看提示';hint.onclick=()=>toast(task.hint);const check=document.createElement('button');check.textContent='验证设计';check.style.marginLeft='7px';check.onclick=checkTask;const result=document.createElement('div');result.id='taskResult';result.className='task-result';result.setAttribute('aria-live','polite');card.append(hint,check,result);box.append(card);}}$('parts').style.display=state.mode==='learn'?'none':'grid';$('subtitle').textContent=state.mode==='free'?'从一对齿轮开始，搭建自己的传动系统。':state.mode==='learn'?'从三个可操作的实验，理解齿数、旋向与传动约束。':'读懂目标，调整设计，用计算结果验证你的方案。';}
function checkTask(){const r=state.result,healthy=!r.overlaps.length&&!r.conflicts.length,pass=healthy&&challenges[state.task].check(state),e=$('taskResult');if(pass){e.textContent='✓ 验证通过，已记录完成！';e.className='task-result success-label';if(!done.includes(state.task)){done.push(state.task);try{localStorage.setItem('gear-workshop-progress',JSON.stringify(done));}catch{}$('progress').textContent=done.length+'/3';const buttons=$('modeContent').querySelectorAll('.mode-options button');buttons[state.task].textContent=challenges[state.task].title+' ✓';}toast('验证通过！可以继续下一项挑战。');}else{e.textContent=r.conflicts.length?'仍有闭环冲突，请移开一处啮合。':r.overlaps.length?'齿轮位置重叠，请先调整布局。':r.ratios[state.output]===undefined?'输出轮尚未连通主动轮。':'尚未达到目标，请核对齿数、旋向和连接。';e.className='task-result error-label';}}
function update(){const r=state.result=C.solve(state.gears,state.motor,state.phase),selected=state.gears.find(g=>g.id===state.selected),out=state.gears.find(g=>g.id===state.output);const bad=r.overlaps.length||r.conflicts.length,ratio=r.ratios[state.output],connected=ratio!==undefined,status=bad?(r.overlaps.length?'齿轮重叠 · 已停止传动':'闭环冲突 · 已停止传动'):Object.keys(r.ratios).length<state.gears.length?'有未连接齿轮':'传动正常';$('systemStatus').textContent=status;$('statusDot').style.background=bad?'#b96046':'#628d62';$('gearCount').textContent=state.gears.length+' 个齿轮 · '+r.edges.length+' 处啮合';$('motorName').textContent=state.motor+' 为主动轮';$('outputName').textContent='齿轮 '+state.output;$('outputSpeed').textContent=bad?'—':connected?format(Math.abs(ratio*state.speed)):'0';$('outputDirection').textContent=bad?'请先修正布局':!connected?'尚未连接主动轮':(ratio*state.direction>0?'顺时针':'逆时针')+' · '+(Math.abs(ratio)<.999?'相对输入减速':Math.abs(ratio)>1.001?'相对输入增速':'与输入等速');$('ratio').textContent=bad||!connected?'—':format(1/ratio,2);$('selectedName').textContent=state.selected;$('teeth').value=selected.z;$('teethValue').textContent=selected.z;$('speed').value=state.speed;$('speedValue').textContent=state.speed;$('reverse').textContent=(state.direction>0?'↻ 顺时针':'↺ 逆时针')+'驱动 · 点击反转';$('play').textContent=state.running?'Ⅱ 暂停':'▶ 播放';$('setMotor').disabled=state.selected===state.motor;$('setOutput').disabled=state.selected===state.output;$('remove').disabled=state.gears.length===1;
const list=$('connectionList');list.replaceChildren();for(const g of state.gears){const el=document.createElement('div'),v=r.ratios[g.id];el.textContent=`${g.id} / ${g.z} 齿　${bad?'停止':v===undefined?'未连接':format(Math.abs(v*state.speed))+' rpm '+(v*state.direction>0?'↻':'↺')}`;if(g.id===state.output){const b=document.createElement('b');b.textContent=el.textContent;el.replaceChildren(b);}list.append(el);}
let title,text;const motor=state.gears.find(g=>g.id===state.motor);if(bad){title=r.overlaps.length?'齿轮之间需要留出正确的中心距离。':'每次外啮合都反向，奇数闭环无法同时转动。';text=r.overlaps.length?'当前齿轮分度圆相互穿入。请拖动齿轮，靠近时松手，让中心距离吸附到两轮分度圆半径之和。':'沿三个齿轮绕行一圈会回到主动轮，却要求它与自己反向，运动约束相互矛盾。将闭环改为开放传动链后，再观察旋向。';}else if(!connected){title='没有啮合连接，就没有传动。';text='拖动输出轮靠近主动轮或其他已连通的齿轮。松手时，系统会在邻近位置自动吸附，虚线表示识别到的啮合关系。';}else{title=state.gears.length>2?'中间轮改变旋向，首末齿数决定转速比。':motor.z<out.z?'小齿轮带大齿轮，转速降低。':motor.z>out.z?'大齿轮带小齿轮，转速提高。':'齿数相同，转速大小相同。';text=`${state.motor} 为输入轮（${motor.z} 齿），${state.output} 为输出轮（${out.z} 齿）。输出转速为 ${state.speed} × ${motor.z} ÷ ${out.z} = ${format(Math.abs(ratio*state.speed))} rpm，${ratio>0?'与输入同向':'与输入反向'}。每经过一处外啮合，旋向改变一次。`;}
$('insightLabel').textContent=state.mode==='learn'?presets[state.lesson].label:state.mode==='challenge'?'挑战任务 / '+challenges[state.task].title:'观察与解释';$('insightTitle').textContent=title;$('explanation').textContent=text;
return r;}
function format(n,d=2){return Number.isInteger(n)?String(n):n.toFixed(d);}
function draw(){update();const gearLayer=$('gears'),links=$('links'),annotations=$('annotations');gearLayer.replaceChildren();links.replaceChildren();annotations.replaceChildren();rotating.clear();const r=state.result,bad=r.overlaps.length||r.conflicts.length;for(const [a,b]of r.edges){const ga=state.gears.find(g=>g.id===a),gb=state.gears.find(g=>g.id===b);links.append(node('line',{x1:ga.x,y1:ga.y,x2:gb.x,y2:gb.y,class:'connection'+(r.conflicts.length?' collision':'')}));}links.style.display=$('pathToggle').checked?'':'none';for(const g of state.gears){const radius=C.radius(g.z),connected=r.ratios[g.id]!==undefined,color=g.id===state.motor?'#507760':connected?'#e4be78':'#c9cfc1',stroke=g.id===state.motor?'#335b48':connected?'#b38c4c':'#a2aea0',group=node('g',{transform:`translate(${g.x} ${g.y})`,class:'gear',tabindex:'0',role:'button','aria-label':`齿轮 ${g.id}，${g.z} 齿。点击选择，方向键移动。`,'data-id':g.id});if(g.id===state.selected)group.append(node('circle',{r:radius+16,class:'select-ring'}));const rotor=node('g');rotor.append(node('path',{d:C.gearPath(g.z),fill:color,stroke,'stroke-width':1.2,filter:'url(#shadow)'}));if($('pitchToggle').checked)rotor.append(node('circle',{r:radius,fill:'none',stroke:g.id===state.motor?'#284a35':'#937741','stroke-width':.8,'stroke-dasharray':'5 5',opacity:.55}));if(radius>=60){for(let i=0;i<4;i++){const a=i*Math.PI/2;rotor.append(node('circle',{cx:Math.cos(a)*radius*.57,cy:Math.sin(a)*radius*.57,r:radius*.19,fill:'#f7f8f1',stroke,'stroke-width':.8}));}}rotor.append(node('path',{d:`M0 -${radius*.37}V-${radius*.78}`,stroke:g.id===state.motor?'#c8dbba':'#a57939','stroke-width':3,'stroke-linecap':'round'}));rotor.append(node('circle',{r:15,fill:'#f7f8f1',stroke,'stroke-width':2}));rotor.append(node('circle',{r:4,fill:stroke}));group.append(rotor);rotating.set(g.id,rotor);group.append(node('text',{y:-radius-28,'text-anchor':'middle',class:'gear-label'},g.id+' · '+g.z+' 齿'));group.append(node('text',{y:radius+35,'text-anchor':'middle',class:'gear-sub'},g.id===state.motor?'输入 '+state.speed+' rpm':g.id===state.output?'输出 '+(!bad&&connected?format(Math.abs(r.ratios[g.id]*state.speed)):'—')+' rpm':connected?'惰轮':'未连接'));if(g.id===state.motor||g.id===state.output){const badge=node('g',{transform:`translate(${radius+12} -14)`});badge.append(node('rect',{x:-15,y:-13,width:30,height:25,rx:5,fill:g.id===state.motor?'#295849':'#d6b06b'}));badge.append(node('text',{'text-anchor':'middle',y:4,fill:g.id===state.motor?'#fff':'#624a22','font-size':10},g.id===state.motor?'入':'出'));group.append(badge);}group.addEventListener('pointerdown',e=>beginDrag(e,g));group.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();state.selected=g.id;draw();}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();state.selected=g.id;g.x+=e.key==='ArrowLeft'?-5:e.key==='ArrowRight'?5:0;g.y+=e.key==='ArrowUp'?-5:e.key==='ArrowDown'?5:0;clamp(g);draw();$('gears').querySelector(`[data-id="${g.id}"]`).focus();}});gearLayer.append(group);}if(bad){annotations.append(node('text',{x:500,y:80,'text-anchor':'middle',fill:'#ac583e','font-size':17},r.overlaps.length?'位置重叠，传动已停止':'奇数闭环：旋向约束相互矛盾'));}pose();}
function pose(){const r=C.solve(state.gears,state.motor,state.phase),bad=r.overlaps.length||r.conflicts.length;for(const g of state.gears){const angle=bad?0:r.angles[g.id]||0;rotating.get(g.id)?.setAttribute('transform',`rotate(${angle*180/Math.PI})`);}}
function coord(e){const p=$('stage').createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform($('stage').getScreenCTM().inverse());}
function clamp(g){const r=C.radius(g.z)+8;g.x=Math.max(r,Math.min(1000-r,g.x));g.y=Math.max(r+25,Math.min(600-r-45,g.y));}
function beginDrag(e,g){if(e.button!==0)return;e.preventDefault();const p=coord(e);state.selected=g.id;drag={id:g.id,dx:p.x-g.x,dy:p.y-g.y};$('stage').setPointerCapture(e.pointerId);draw();}
$('stage').addEventListener('pointermove',e=>{if(!drag)return;const g=state.gears.find(g=>g.id===drag.id),p=coord(e);g.x=p.x-drag.dx;g.y=p.y-drag.dy;clamp(g);draw();});
function finishDrag(){if(!drag)return;const g=state.gears.find(g=>g.id===drag.id);Object.assign(g,C.snap(g,state.gears.filter(h=>h!==g)));clamp(g);drag=null;state.phase=0;draw();}
$('stage').addEventListener('pointerup',finishDrag);$('stage').addEventListener('pointercancel',finishDrag);
function add(z){if(state.gears.length>=12)return toast('工作台最多容纳 12 个齿轮。');const id='ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').find(k=>!state.gears.some(g=>g.id===k)),base=state.gears.find(g=>g.id===state.selected);let g={id,z,x:800,y:400},found=false;for(const h of [base,...state.gears.filter(h=>h!==base)]){for(let i=0;i<16;i++){const a=i*Math.PI/8,r=C.radius(z)+C.radius(h.z),x=h.x+Math.cos(a)*r,y=h.y+Math.sin(a)*r,rad=C.radius(z)+10;if(x<rad||x>1000-rad||y<rad+30||y>600-rad-45)continue;if(state.gears.every(o=>Math.hypot(x-o.x,y-o.y)>=C.radius(z)+C.radius(o.z)-2)){g={id,z,x,y};found=true;break;}}if(found)break;}if(!found)return toast('当前空间不足，请先移开或删除部分齿轮。');state.gears.push(g);state.selected=id;state.output=id;draw();toast('已加入 '+z+' 齿齿轮 '+id+'，并设为输出轮。');}
for(const z of C.TEETH){const b=document.createElement('button');b.className='part';b.setAttribute('aria-label','加入 '+z+' 齿齿轮');const svg=node('svg',{viewBox:'-130 -130 260 260','aria-hidden':'true'});svg.append(node('path',{d:C.gearPath(z),fill:'#a6b99b',stroke:'#6b8762','stroke-width':2}));svg.append(node('circle',{r:12,fill:'#f3f4eb'}));const label=document.createElement('span');label.textContent=z+' 齿';const sub=document.createElement('b');sub.textContent='＋ 加入';b.append(svg,label,sub);b.onclick=()=>add(z);$('parts').append(b);}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;modeUI();reset();});$('speed').oninput=e=>{state.speed=+e.target.value;draw();};$('reverse').onclick=()=>{state.direction*=-1;draw();};$('play').onclick=()=>{state.running=!state.running;update();};$('reset').onclick=()=>{reset();toast('已恢复当前实验的初始布局。');};$('pitchToggle').onchange=draw;$('pathToggle').onchange=draw;
$('teeth').onchange=e=>{const g=state.gears.find(g=>g.id===state.selected),neighbors=state.result.edges.filter(e=>e.includes(g.id)).map(e=>state.gears.find(h=>h.id===e.find(id=>id!==g.id))),anchor=neighbors[0];g.z=+e.target.value;if(anchor){const a=Math.atan2(g.y-anchor.y,g.x-anchor.x),r=C.radius(g.z)+C.radius(anchor.z);g.x=anchor.x+Math.cos(a)*r;g.y=anchor.y+Math.sin(a)*r;}clamp(g);Object.assign(g,C.snap(g,state.gears.filter(h=>h!==g)));state.phase=0;draw();};
$('setMotor').onclick=()=>{state.motor=state.selected;state.phase=0;draw();};$('setOutput').onclick=()=>{state.output=state.selected;draw();};$('remove').onclick=()=>{if(state.gears.length===1)return;const id=state.selected;state.gears=state.gears.filter(g=>g.id!==id);state.selected=state.gears[0].id;if(state.motor===id)state.motor=state.selected;if(state.output===id)state.output=state.gears[state.gears.length-1].id;draw();};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('save').onclick=()=>{download(new Blob([JSON.stringify({format:'gear-workshop-v1',gears:state.gears,motor:state.motor,output:state.output,speed:state.speed,direction:state.direction},null,2)],{type:'application/json'}),'齿轮工坊设计.json');toast('设计已保存，可用“打开设计”恢复。');};$('load').onclick=()=>$('file').click();$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('设计文件过大，请选择本项目导出的 JSON。');const data=C.validateDesign(JSON.parse(await file.text()));Object.assign(state,data,{mode:'free',selected:data.output,phase:0});modeUI();draw();toast('设计已恢复。');}catch(err){toast(err.message||'无法读取该设计文件。');}finally{e.target.value='';}};
$('export').onclick=async()=>{const snapshot=$('stage').cloneNode(true);snapshot.setAttribute('xmlns',NS);snapshot.style.background='#f7f8f1';snapshot.querySelectorAll('g.gear').forEach(e=>{e.removeAttribute('tabindex');e.removeAttribute('role');});const style=node('style');style.textContent='.gear-label{font-family:Microsoft YaHei,sans-serif;font-size:18px;fill:#3b5448}.gear-sub{font-family:Microsoft YaHei,sans-serif;font-size:12px;fill:#7d8d7e}.connection{stroke:#a9baa4;stroke-width:1.5;stroke-dasharray:5 5}.collision{stroke:#b96046}.select-ring{display:none}';snapshot.insertBefore(style,snapshot.firstChild);const title=node('text',{x:36,y:42,fill:'#244b42','font-size':23,'font-family':'Microsoft YaHei,sans-serif'},'齿轮工坊 · 机械传动实验');snapshot.append(title);snapshot.append(node('text',{x:36,y:575,fill:'#6d7d72','font-size':13,'font-family':'Microsoft YaHei,sans-serif'},`输入 ${state.motor} / ${state.speed} rpm　输出 ${state.output} / ${$('outputSpeed').textContent} rpm　总传动比 ${$('ratio').textContent}`));const blob=new Blob([new XMLSerializer().serializeToString(snapshot)],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});const canvas=document.createElement('canvas');canvas.width=2000;canvas.height=1200;const ctx=canvas.getContext('2d');ctx.fillStyle='#f7f8f1';ctx.fillRect(0,0,2000,1200);ctx.drawImage(image,0,0,2000,1200);const png=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!png)throw Error();download(png,'齿轮工坊实验记录.png');toast('实验图已导出。');}catch{toast('图片导出失败，请使用浏览器截图。');}finally{URL.revokeObjectURL(url);}};
function modal(html){$('dialogContent').innerHTML=html;$('dialog').showModal();}$('closeDialog').onclick=()=>$('dialog').close();$('dialog').onclick=e=>{if(e.target===$('dialog')&&(e.clientX<$('dialog').getBoundingClientRect().left||e.clientX>$('dialog').getBoundingClientRect().right))$('dialog').close();};
$('help').onclick=()=>modal('<p class="eyebrow">欢迎来到齿轮工坊</p><h2>从搭建，到理解。</h2><h3>1. 放上齿轮</h3><p>在零件架点击 20、30、40 或 60 齿。加入的齿轮会尝试放到选中轮附近，并成为输出轮。</p><h3>2. 拖动并连接</h3><p>拖动齿轮靠近另一个，松手后自动吸附。点击选中，再用方向键每次微调 5 个单位。选中轮可改变齿数、设为输入或输出。</p><h3>3. 观察和验证</h3><p>右侧实时显示转速与传动比。教学实验提供三组示例；挑战任务通过实际传动结果验证。按 Esc 关闭此窗口。</p><p>使用“保存设计”保留 JSON 文件，“导出实验图”保存 PNG。学习进度仅保存在当前浏览器；离线文件模式下，部分浏览器可能限制本地进度保存。</p>');
$('about').onclick=()=>modal('<p class="eyebrow">原理与资料</p><h2>每一转，都有依据。</h2><p>分度圆半径 r = mz/2；本作品使用统一模数 m = 4。相邻外啮合齿轮的中心距为两轮分度圆半径之和。理想条件下 n₁z₁ = −n₂z₂，每一处外啮合都改变旋向。</p><p>程序以齿轮为节点、啮合为边，从主动轮遍历求解转速。沿不同路径到达同一节点时，若要求的转速不一致，则判为约束冲突。分度圆明显重叠时暂停传动。</p><p>齿廓以 20° 压力角渐开线采样绘制，用于科普示意。本模型不计算摩擦、背隙、弹性、齿根强度及动力负载，不作为机械制造设计依据。</p><h3>参考资料</h3><p>MIT OpenCourseWare, 2.72 Elements of Mechanical Design, Lecture 12: Belt, friction, gear drives（2009）。资料仅作为运动学原理参考，页面图形由本程序绘制。</p><p><a href="https://ocw.mit.edu/courses/2-72-elements-of-mechanical-design-spring-2009/83d81a6f63d1c6f0fb775c08b207bc51_MIT2_72s09_lec12.pdf" target="_blank" rel="noopener">查看 MIT 课程资料 ↗（需联网）</a></p>');
function frame(t){const dt=Math.min((t-last)/1000,.05);last=t;if(state.running&&!drag&&!state.result.overlaps.length&&!state.result.conflicts.length){state.phase=(state.phase+dt*state.speed/60*C.TAU*state.direction)%(C.TAU*120);pose();}requestAnimationFrame(frame);}modeUI();reset();requestAnimationFrame(frame);
// 只读状态快照，便于课堂演示核对与自动验证。
window.GearWorkshop={snapshot:()=>JSON.parse(JSON.stringify({...state,done})),loadPreset:i=>{if(i<0||i>=presets.length)return;state.mode='learn';state.lesson=i;modeUI();reset();}};
})();
